          },
          "sec_introduction_p7_s1": {
            "action": "replace",
            "text": "본 논문은 서론을 시작으로 연구 배경과 문제 제기, 실험 조건 및 구성, 최적화 과정과 관측 결과, 해석 한계, 결론의 순서로 구성된다.",
            "join_previous": false
          },
          "sec_introduction_p8_s1": {
            "action": "delete",
